css:
.fx-ph{width:min(1000px,100%);display:grid;gap:2.4em;text-align:center}
.fx-ph h2{font-size:clamp(2em,4.6vw,3em)}.fx-ph .sub{opacity:.65;margin-top:.5em}
.fx-ph .plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2em;align-items:center;text-align:left}
.fx-ph .plan{position:relative;padding:1.8em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text));display:grid;gap:1.1em;transition:transform calc(.35s/var(--speed)) ease,box-shadow calc(.35s/var(--speed)) ease}
.fx-ph .plan:hover{transform:translateY(-6px);box-shadow:0 26px 40px -28px color-mix(in srgb,var(--text) 60%,transparent)}
.fx-ph .plan h3{font-size:1.2em}.fx-ph .d{opacity:.65;font-size:.9em}
.fx-ph .price b{font:600 3em/1 var(--font-heading)}.fx-ph .price small{opacity:.6;margin-left:.3em}
.fx-ph ul{list-style:none;margin:0;padding:0;display:grid;gap:.6em;font-size:.93em}
.fx-ph li{display:flex;gap:.65em;align-items:center}.fx-ph li::before{content:"✓";flex:none;width:1.5em;height:1.5em;border-radius:50%;display:grid;place-items:center;font-size:.72em;font-weight:800;background:color-mix(in srgb,var(--accent) 22%,transparent);color:var(--text)}
.fx-ph .btn{display:block;text-align:center;padding:.9em 1em;border-radius:var(--radius);font-weight:700;text-decoration:none;border:1.5px solid var(--primary);color:var(--primary);transition:background .25s,color .25s}
.fx-ph .btn:hover{background:var(--primary);color:var(--on-primary)}.fx-ph .btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-ph .feat{background:var(--primary);color:var(--on-primary);border-color:var(--primary);padding:2.3em 1.8em;transform:scale(1.04);box-shadow:0 30px 50px -30px var(--primary)}
.fx-ph .feat:hover{transform:scale(1.04) translateY(-6px)}
.fx-ph .feat .d{opacity:.8}.fx-ph .feat li::before{background:color-mix(in srgb,var(--on-primary) 20%,transparent);color:var(--on-primary)}
.fx-ph .feat .btn{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}.fx-ph .feat .btn:hover{filter:brightness(1.08)}
.fx-ph .feat .btn:focus-visible{outline-color:var(--on-primary)}
.fx-ph .rib{position:absolute;top:1.1em;right:1.1em;padding:.3em .8em;border-radius:99px;font-size:.72em;font-weight:800;letter-spacing:.08em;text-transform:uppercase;background:var(--accent);color:var(--on-accent)}
@media(max-width:860px){.fx-ph .plans{grid-template-columns:1fr}.fx-ph .feat,.fx-ph .feat:hover{transform:none}
.fx-ph .feat.is-tap{transform:none}}
@media(prefers-reduced-motion:reduce){.fx-ph .plan{transition:none}.fx-ph .plan:hover{transform:none}.fx-ph .feat:hover{transform:scale(1.04)}
.fx-ph .plan.is-tap{transform:none}
.fx-ph .feat.is-tap{transform:scale(1.04)}}
/* touch: :hover mirrored as .is-tap */
.fx-ph .plan.is-tap{transform:translateY(-6px);box-shadow:0 26px 40px -28px color-mix(in srgb,var(--text) 60%,transparent)}
.fx-ph .btn.is-tap{background:var(--primary);color:var(--on-primary)}
.fx-ph .feat.is-tap{transform:scale(1.04) translateY(-6px)}
.fx-ph .feat .btn.is-tap{filter:brightness(1.08)}
